import {mkdtemp,writeFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
const modules={"addressing.ts":"/**\n * PGSL content-addressing — the public/private dedup split + the node-address\n * codec used as FoundationDB keys.\n *\n * Two decisions (maintainer, 2026-07-08) are realized here:\n *\n *  1. DEDUP DOMAIN by sensitivity. A PGSL atom's identity is a hash of its VALUE,\n *     which globally de-duplicates identical values — a feature (cross-agent\n *     structural overlap detectable from public projections) but also a leak: the\n *     content-addressed `set-if-absent` write lets any writer probe whether a\n *     value already exists by minting `sha256(guess)` and checking presence\n *     (guess-and-check on e.g. an SSN), cross-tenant, with no read access. So:\n *       - PUBLIC atoms keep the bare global hash (the overlap feature; existence\n *         of public content is not secret). Wire-identical to @interego/pgsl's\n *         `atomUri` so public atoms stay compatible with the existing lattice.\n *       - PRIVATE / confidential atoms are addressed by an HMAC keyed by the\n *         owning tenant's secret. Identical private values under different tenant\n *         keys get different addresses (no cross-tenant dedup), and — crucially —\n *         a party without the tenant key cannot compute the address at all, which\n *         CLOSES the existence oracle. Same value + same tenant key still dedups\n *         within the tenant.\n *     The URN SHAPE is identical for both (40 hex), so the address never leaks\n *     whether an atom is public or private.\n *\n *  2. The FDB key form of a node URN is a compact 21-byte address (1 kind byte +\n *     the 20 raw bytes behind the 40 hex chars), keeping atoms and fragments in\n *     disjoint, contiguous key ranges well under FDB's ideal key size.\n *\n * Pure module: only `node:crypto`. No FDB, no lattice state.\n */\n\nimport { createHash, createHmac } from 'node:crypto';\n\nexport type AtomValue = string | number | boolean;\nexport type Sensitivity = 'public' | 'private';\n\nexport interface AtomAddressOptions {\n  /** Default 'public'. 'private' requires `tenantKey`. */\n  sensitivity?: Sensitivity;\n  /** The owning tenant's secret; required (and only used) when sensitivity is 'private'. */\n  tenantKey?: string;\n}\n\nconst ATOM_PREFIX = 'urn:pgsl:atom:';\nconst FRAGMENT_PREFIX = 'urn:pgsl:fragment:';\nconst HASH_HEX_LEN = 40;\nconst HASH_BYTES = HASH_HEX_LEN / 2; // 20\n\nfunction sha40(input: string): string {\n  return createHash('sha256').update(input).digest('hex').slice(0, HASH_HEX_LEN);\n}\nfunction hmac40(key: string, input: string): string {\n  return createHmac('sha256', key).update(input).digest('hex').slice(0, HASH_HEX_LEN);\n}\n\n/**\n * Public atom address — bare hash, globally de-duplicated. The 40-hex hash is\n * identical to `@interego/pgsl`'s `atomUri` (`sha256(\"atom:\" + String(value))[:40]`),\n * but atomUri now mints the dereferenceable URL id (`…/ns/pgsl/atom/<hash>`) while\n * this emits the legacy `urn:pgsl:atom:<hash>`, so the two id STRINGS are no longer\n * byte-identical — they differ only by scheme. The FDB node-address codec\n * ({@link nodeAddrFromUrn}) strips the scheme, so both forms resolve to the same\n * key and public atoms stay wire-compatible with the current lattice. An external\n * party CAN recompute this — existence of PUBLIC content is not secret; this is\n * exactly the cross-agent structural-overlap primitive.\n */\nexport function publicAtomAddress(value: AtomValue): string {\n  return ATOM_PREFIX + sha40('atom:' + String(value));\n}\n\n/**\n * Private/confidential atom address — HMAC-SHA256 keyed by the owning tenant's\n * secret. Same value under two tenant keys → two different addresses (no\n * cross-tenant dedup); a party without the tenant key cannot compute the address\n * (closes the content-addressed existence oracle). Same value + same key still\n * dedups within the tenant.\n */\nexport function privateAtomAddress(value: AtomValue, tenantKey: string): string {\n  if (!tenantKey) throw new Error('privateAtomAddress requires a non-empty tenantKey');\n  return ATOM_PREFIX + hmac40(tenantKey, 'atom:' + String(value));\n}\n\n/**\n * Address an atom by sensitivity. Public (default) = bare global hash; private =\n * tenant-keyed HMAC. Throws if 'private' is requested without a `tenantKey`.\n */\nexport function atomAddress(value: AtomValue, opts: AtomAddressOptions = {}): string {\n  const sensitivity = opts.sensitivity ?? 'public';\n  if (sensitivity === 'private') {\n    if (!opts.tenantKey) throw new Error(\"atomAddress: sensitivity 'private' requires opts.tenantKey\");\n    return privateAtomAddress(value, opts.tenantKey);\n  }\n  return publicAtomAddress(value);\n}\n\n// ── Node-address codec (URN ↔ 21-byte FDB key) ──────────────────\n\nexport type NodeKind = 'atom' | 'fragment';\nexport const KIND_ATOM = 0x01;\nexport const KIND_FRAGMENT = 0x02;\n\n/** The FDB key form of a node URN: kind byte + the 20 raw hash bytes. */\nexport interface NodeAddr {\n  kind: NodeKind;\n  /** 20 bytes — the raw form of the URN's 40 hex chars. */\n  hash: Uint8Array;\n}\n\nexport function kindByte(kind: NodeKind): number {\n  return kind === 'atom' ? KIND_ATOM : KIND_FRAGMENT;\n}\n\n/**\n * Parse a PGSL node id into a NodeAddr. DUAL-READ: accepts BOTH the legacy\n * `urn:pgsl:<kind>:<40hex>` and the current dereferenceable URL form\n * `https://…/ns/pgsl/<kind>/<40hex>`. The FDB codec strips the scheme, so both\n * forms yield an identical 21-byte address. Parsed inline (no @interego/core\n * import) to keep this a pure `node:crypto`-only module — it is loaded by the\n * CSS-over-PGSL harness in an isolated module context.\n */\nexport function nodeAddrFromUrn(urn: string): NodeAddr {\n  let kind: NodeKind | null = null;\n  let hex: string | null = null;\n  if (urn.startsWith(ATOM_PREFIX)) { kind = 'atom'; hex = urn.slice(ATOM_PREFIX.length); }\n  else if (urn.startsWith(FRAGMENT_PREFIX)) { kind = 'fragment'; hex = urn.slice(FRAGMENT_PREFIX.length); }\n  else {\n    const m = /\\/ns\\/pgsl\\/(atom|fragment)\\/([0-9a-fA-F]{40})\\b/.exec(urn);\n    if (m) { kind = m[1]!.toLowerCase() as NodeKind; hex = m[2]!; }\n  }\n  if (kind === null || hex === null) throw new Error(`not a pgsl node id: ${urn}`);\n  hex = hex.toLowerCase();\n  if (!/^[0-9a-f]{40}$/.test(hex)) throw new Error(`malformed pgsl node hash: ${urn}`);\n  const hash = new Uint8Array(HASH_BYTES);\n  for (let i = 0; i < HASH_BYTES; i++) hash[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);\n  return { kind, hash };\n}\n\n/** Inverse of {@link nodeAddrFromUrn}. */\nexport function urnFromNodeAddr(addr: NodeAddr): string {\n  if (addr.hash.length !== HASH_BYTES) throw new Error(`NodeAddr.hash must be ${HASH_BYTES} bytes`);\n  const hex = Array.from(addr.hash, (b) => b.toString(16).padStart(2, '0')).join('');\n  return (addr.kind === 'atom' ? ATOM_PREFIX : FRAGMENT_PREFIX) + hex;\n}\n","keyspace.ts":"/**\n * Order-preserving key encoding for the PGSL store's FoundationDB subspaces.\n *\n * Keys are opaque bytes to FDB; ordering is bytewise. We keep the encoding\n * entirely inside this package (both the in-memory fake and the eventual real\n * FDB adapter store these exact byte keys), so we only need it to be\n * bytewise-order-preserving for the ranges we scan. Fixed-width node addresses\n * and big-endian ints sort correctly; string-keyed subspaces are 0x00-delimited\n * for clean prefix ranges.\n *\n * Subspaces:\n *   N   content-addressed nodes         [kindByte][hash20]\n *   CI  fragment -> ordered items       [fragHash20][pos:u32]        -> item urn\n *   CB  item -> containing fragments    [itemAddr21][fragHash20]      -> pos:u32\n *   LFT/RGT  pullback constituents      [childHash20][fragHash20]\n *   LV  level slice                     [level:u32][nodeAddr21]\n *   OV  LDP resource -> holon           [pod]0[resource]              -> top urn\n *   OVR holon -> projecting resources   [topHash20]0[pod]0[resource]\n *   PR  retained persistence registry   [nodeAddr21][tier:u32]        -> record\n *   AA  per-atom ABAC attributes        [scope]0[atomAddr21]          -> attrs\n *   AAX classification index            [scope]0[classOrd:u32][atomAddr21]\n *   CP  mutable control-plane           [collection]0[id]            -> doc\n */\n\nimport type { NodeAddr } from './addressing.ts';\nimport { kindByte } from './addressing.ts';\nimport type { Key } from './fdb-like.js';\n\nconst ROOT = new TextEncoder().encode('pgsl\\x00');\nconst TAG_N = 0x4e;  // N nodes\nconst TAG_CI = 0x49; // I fragment->items\nconst TAG_CB = 0x42; // B item->fragments\nconst TAG_LFT = 0x4c; // L left constituents\nconst TAG_RGT = 0x52; // R right constituents\nconst TAG_LV = 0x56; // V level slice\nconst TAG_OV = 0x4f; // O overlay resource->holon\nconst TAG_OVR = 0x57; // W holon->resources\nconst TAG_PR = 0x50; // P persistence registry\nconst TAG_AA = 0x41; // A atom attributes\nconst TAG_AAX = 0x58; // X classification index\nconst TAG_CP = 0x43; // C control-plane\n\nconst utf8 = (s: string): Uint8Array => new TextEncoder().encode(s);\nconst B = (n: number): Uint8Array => Uint8Array.of(n);\nfunction u32be(n: number): Uint8Array {\n  if (!Number.isInteger(n) || n < 0 || n > 0xffffffff) throw new Error(`u32be out of range: ${n}`);\n  return Uint8Array.of((n >>> 24) & 0xff, (n >>> 16) & 0xff, (n >>> 8) & 0xff, n & 0xff);\n}\nfunction concat(...parts: Uint8Array[]): Uint8Array {\n  let len = 0;\n  for (const p of parts) len += p.length;\n  const out = new Uint8Array(len);\n  let o = 0;\n  for (const p of parts) { out.set(p, o); o += p.length; }\n  return out;\n}\n/** The 21-byte in-key node address: kind byte + 20 hash bytes. */\nfunction addrBytes(addr: NodeAddr): Uint8Array {\n  return concat(B(kindByte(addr.kind)), addr.hash);\n}\n\n/** Exclusive upper bound for a prefix range (FDB `strinc`). */\nexport function strinc(prefix: Uint8Array): Uint8Array {\n  const b = prefix.slice();\n  for (let i = b.length - 1; i >= 0; i--) {\n    if (b[i]! < 0xff) { b[i] = b[i]! + 1; return b.slice(0, i + 1); }\n  }\n  throw new Error('strinc: prefix is all 0xff (no successor)');\n}\nfunction range(prefix: Uint8Array): { begin: Key; end: Key } {\n  return { begin: prefix, end: strinc(prefix) };\n}\n\n/** The single-letter subspaces, named as the header comment names them. */\nexport type SubspaceTag = 'N' | 'I' | 'B' | 'L' | 'R' | 'V' | 'O' | 'W' | 'P' | 'A' | 'X' | 'C';\nconst TAG_OF: Record<SubspaceTag, number> = { N: TAG_N, I: TAG_CI, B: TAG_CB, L: TAG_LFT, R: TAG_RGT, V: TAG_LV, O: TAG_OV, W: TAG_OVR, P: TAG_PR, A: TAG_AA, X: TAG_AAX, C: TAG_CP };\n/** The whole key range of one subspace, for a collector that must see every row of it. */\nexport function subspaceRange(tag: SubspaceTag): { begin: Key; end: Key } {\n  return range(concat(ROOT, B(TAG_OF[tag])));\n}\n/** Byte offset of a subspace's own payload: the root prefix plus the tag byte. */\nexport const SUBSPACE_PAYLOAD_OFFSET = ROOT.length + 1;\n/** The 21-byte in-key address of a node, exported for readers of P / V / A / X keys. */\nexport function nodeAddrBytes(addr: NodeAddr): Uint8Array { return addrBytes(addr); }\n\n// ── N: content-addressed nodes ──\nexport function nodeKey(addr: NodeAddr): Key { return concat(ROOT, B(TAG_N), addrBytes(addr)); }\nexport function nodeRange(): { begin: Key; end: Key } { return range(concat(ROOT, B(TAG_N))); }\n\n// ── CI: fragment -> ordered items (value = item urn) ──\nexport function ciKey(fragHash: Uint8Array, pos: number): Key {\n  return concat(ROOT, B(TAG_CI), fragHash, u32be(pos));\n}\nexport function ciRange(fragHash: Uint8Array): { begin: Key; end: Key } {\n  return range(concat(ROOT, B(TAG_CI), fragHash));\n}\n\n// ── CB: item -> containing fragments (value = pos) ──\nexport function cbKey(itemAddr: NodeAddr, fragHash: Uint8Array): Key {\n  return concat(ROOT, B(TAG_CB), addrBytes(itemAddr), fragHash);\n}\nexport function cbRange(itemAddr: NodeAddr): { begin: Key; end: Key } {\n  return range(concat(ROOT, B(TAG_CB), addrBytes(itemAddr)));\n}\n/** Extract the fragment hash (last 20 bytes) from a CB key. */\nexport function cbFragHash(key: Key): Uint8Array { return key.slice(key.length - 20); }\n\n// ── LFT / RGT: pullback constituents ──\nexport function lftKey(childHash: Uint8Array, fragHash: Uint8Array): Key {\n  return concat(ROOT, B(TAG_LFT), childHash, fragHash);\n}\nexport function rgtKey(childHash: Uint8Array, fragHash: Uint8Array): Key {\n  return concat(ROOT, B(TAG_RGT), childHash, fragHash);\n}\n\n// ── LV: level slice ──\nexport function lvKey(level: number, addr: NodeAddr): Key {\n  return concat(ROOT, B(TAG_LV), u32be(level), addrBytes(addr));\n}\nexport function lvRange(level: number): { begin: Key; end: Key } {\n  return range(concat(ROOT, B(TAG_LV), u32be(level)));\n}\n/** Extract the 21-byte node address (last 21 bytes) from an LV key. */\nexport function lvAddrBytes(key: Key): Uint8Array { return key.slice(key.length - 21); }\n\n// ── OV / OVR: overlay ──\nexport function ovKey(pod: string, resource: string): Key {\n  return concat(ROOT, B(TAG_OV), utf8(pod), B(0), utf8(resource));\n}\nexport function ovrKey(topHash: Uint8Array, pod: string, resource: string): Key {\n  return concat(ROOT, B(TAG_OVR), topHash, B(0), utf8(pod), B(0), utf8(resource));\n}\n\n// ── PR: retained persistence registry ──\nexport function prKey(addr: NodeAddr, tier: number): Key {\n  return concat(ROOT, B(TAG_PR), addrBytes(addr), u32be(tier));\n}\n\n// ── AA / AAX: per-atom ABAC attributes ──\nexport function aaKey(scope: string, atomAddr: NodeAddr): Key {\n  return concat(ROOT, B(TAG_AA), utf8(scope), B(0), addrBytes(atomAddr));\n}\nexport function aaScopeRange(scope: string): { begin: Key; end: Key } {\n  return range(concat(ROOT, B(TAG_AA), utf8(scope), B(0)));\n}\n/** Extract the 21-byte atom address (last 21 bytes) from an AA key. */\nexport function aaAtomAddrBytes(key: Key): Uint8Array { return key.slice(key.length - 21); }\nexport function aaxKey(scope: string, classOrdinal: number, atomAddr: NodeAddr): Key {\n  return concat(ROOT, B(TAG_AAX), utf8(scope), B(0), u32be(classOrdinal), addrBytes(atomAddr));\n}\nexport function aaxAtLeastRange(scope: string, minOrdinal: number): { begin: Key; end: Key } {\n  const scopePrefix = concat(ROOT, B(TAG_AAX), utf8(scope), B(0));\n  return { begin: concat(scopePrefix, u32be(minOrdinal)), end: strinc(scopePrefix) };\n}\n\n// ── CP: mutable control-plane ──\nexport function cpKey(collection: string, id: string): Key {\n  return concat(ROOT, B(TAG_CP), utf8(collection), B(0), utf8(id));\n}\nexport function cpRange(collection: string): { begin: Key; end: Key } {\n  return range(concat(ROOT, B(TAG_CP), utf8(collection), B(0)));\n}\nexport function cpListRange(collection: string, idPrefix: string): { begin: Key; end: Key } {\n  return range(concat(ROOT, B(TAG_CP), utf8(collection), B(0), utf8(idPrefix)));\n}\n/** Extract the id (the part after the collection separator) from a CP key. */\nexport function cpIdFromKey(collection: string, key: Key): string {\n  const prefixLen = ROOT.length + 1 + utf8(collection).length + 1;\n  return new TextDecoder().decode(key.slice(prefixLen));\n}\n","gc-atom-header.ts":"/**\n * Bounded topology for the canonical atom encoding written by LdpStore.\n * An atom has no outgoing edges. Large canonical opaque atoms need only their\n * header; unexpected historical encodings fall back to the complete JSON reader.\n */\nexport const ATOM_HEADER_BYTES = 512;\nexport interface AtomTopology { kind: 'atom'; level: 0; }\nconst prefix = [0x70, 0x67, 0x73, 0x6c, 0, 0x4e] as const;\nfunction hashFromUri(uri: unknown): string | null {\n  if (typeof uri !== 'string') return null;\n  const match = /^urn:pgsl:atom:([0-9a-f]{40})$/i.exec(uri)\n    ?? /^https?:\\/\\/[^\"\\\\\\s]+\\/ns\\/pgsl\\/atom\\/([0-9a-f]{40})$/i.exec(uri);\n  return match?.[1]?.toLowerCase() ?? null;\n}\nexport function atomTopologyFromPrefix(key: Uint8Array, bytes: Uint8Array, valueBytes: number): AtomTopology | null {\n  if (key.length !== 27 || prefix.some((b, i) => key[i] !== b) || key[6] !== 1\n    || !Number.isSafeInteger(valueBytes) || valueBytes < 0\n    || bytes.length !== Math.min(valueBytes, ATOM_HEADER_BYTES)) {\n    throw new Error('refusing collection: invalid atom header record');\n  }\n  const expectedHash = Array.from(key.subarray(7), b => b.toString(16).padStart(2, '0')).join('');\n  const text = new TextDecoder().decode(bytes);\n  let uri: unknown;\n  if (valueBytes <= ATOM_HEADER_BYTES) {\n    let parsed: unknown;\n    try { parsed = JSON.parse(text); } catch { return null; }\n    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;\n    const node = parsed as Record<string, unknown>;\n    if (node.kind !== 'atom' || node.level !== 0) return null;\n    uri = node.uri;\n  } else {\n    // encodeNode(JSON.stringify) preserves LdpStore's uri/kind/level/value order.\n    // Do not infer topology from a value/provenance substring or an escaped URI.\n    const match = /^\\{\"uri\":\"([^\"\\\\]+)\",\"kind\":\"atom\",\"level\":0,\"value\":\"/.exec(text);\n    if (!match) return null;\n    uri = match[1];\n  }\n  const actualHash = hashFromUri(uri);\n  if (actualHash === null) return null;\n  if (actualHash !== expectedHash) throw new Error('refusing collection: atom header does not match node key');\n  return { kind: 'atom', level: 0 };\n}\n","gc.ts":"/**\n * Garbage collection for a grow-only, content-addressed node store.\n *\n * ── WHY THIS EXISTS ────────────────────────────────────────────────────────────────────────────\n *\n * `LdpStore` implements PUT-overwrite by repointing a resource's mutable record at new nodes;\n * the previous nodes \"simply become unreferenced\" (ldp.ts). Nothing ever removed them. On the\n * production pod store that meant one pod's manifest, rewritten a few thousand times while it\n * was 30 to 45 MB, kept every copy: 45 GB in a table whose live content is a small fraction of\n * that, until the volume filled and Postgres stopped writing (2026-09-20).\n *\n * ── WHAT \"LIVE\" MEANS ─────────────────────────────────────────────────────────────────────────\n *\n * Roots are everything the mutable subspaces point at:\n *   C  control-plane records: an LDP ResourceRecord names topUri, opaqueUri and chunkUris; any\n *      other collection is kept whole and any node URN inside it is a root as well;\n *   O  overlay resource -> holon: the value is the top node's URN;\n *   A / X  per-atom attributes and their classification index: the atom in the key is a root\n *      (an attribute someone set is a claim about that atom, whatever else references it);\n *   P  persistence registry: rows whose tier is not the derived tier 2 are roots.\n * From the roots, a fragment reaches its items (I is written from `items`), and a level >= 2\n * fragment reaches its left and right constituents. Every node reached is live.\n *\n * The keys to keep are then reconstructed exactly as `PgslStore.compose` wrote them — N, V and\n * P per node; I, B, L, R per fragment — plus the W rows whose top node is live, plus every row\n * of C, O, A and X. Everything else in the table is garbage: unreferenced nodes and the\n * projection rows that only they justify.\n *\n * ── HOW IT IS APPLIED ─────────────────────────────────────────────────────────────────────────\n *\n * Deleting tens of millions of rows leaves a table just as large until it is rewritten, and a\n * rewrite of a 45 GB table needs 45 GB free. The live set is small, so `rebuildTable` copies\n * the live rows into a new table under a budgeted ACCESS EXCLUSIVE attempt. The collection\n * runs inside that lock, so nothing written during the copy can be missed. NOWAIT refuses\n * contention; a short monotonic SQL work budget aborts a long traversal/copy. Only a completed\n * attempt swaps the names and leaves the old table for later verified retirement. Large live\n * graphs can therefore defer compaction; this is not an online collector. Durable COMMIT and\n * network/scheduling latency are not an absolute wall-clock bound. `tools/pgsl-store-gc.ts`\n * drives it; a dry run only reads.\n */\n\nimport { kindByte, nodeAddrFromUrn, type NodeAddr, type NodeKind } from './addressing.ts';\nimport { performance } from 'node:perf_hooks';\nimport type { FdbLike } from './fdb-like.js';\nimport {\n  SUBSPACE_PAYLOAD_OFFSET, cbKey, ciKey, cpKey, lftKey, lvKey, nodeAddrBytes, nodeKey, prKey, rgtKey, subspaceRange, type SubspaceTag,\n} from './keyspace.ts';\nimport type { StoredNode } from './node.js';\nimport { ATOM_HEADER_BYTES, atomTopologyFromPrefix } from './gc-atom-header.ts';\n\nconst dec = new TextDecoder();\nconst nodeDec = new TextDecoder('utf-8', { fatal: true });\n// Root recognition must use the same dual-read codec as fragment edges.\n// Otherwise a current URL-form head would be omitted from the live closure.\nfunction isNodeIdentifier(value: string): boolean {\n  if (!value.startsWith('urn:pgsl:') && !value.includes('/ns/pgsl/')) return false;\n  try { nodeAddrFromUrn(value); return true; } catch { return false; }\n}\nconst ADDR_BYTES = 21;\nconst HASH_BYTES = 20;\n// Large opaque atoms are commonly ~700 KiB. A 2,000-node fetch can allocate\n// over a gigabyte before traversal starts; keep each fetch small instead.\nconst TRAVERSAL_BATCH_SIZE = 32;\nexport type NodeTopology = Pick<StoredNode, 'kind' | 'level' | 'items' | 'left' | 'right'>;\nexport interface NodeTopologyRecord {\n  /** Null records an unreadable node; collection must not authorize cleanup. */\n  readonly topology: NodeTopology | null;\n  /** Exact original stored value bytes, never the projected JSON length. */\n  readonly byteLength: number;\n}\n\n/** Collector reads; `readerFromFdb` serves tests, `readerFromPg` production. */\nexport interface KvReader {\n  /** Every row of [begin, end) in key order, paged; `onRow` may be async. */\n  scan(begin: Uint8Array, end: Uint8Array, onRow: (key: Uint8Array, value: Uint8Array) => void): Promise<void>;\n  /** The values of the given keys, by hex key; absent keys are simply missing from the map. */\n  getMany(keys: readonly Uint8Array[]): Promise<Map<string, Uint8Array>>;\n  /** Optional payload-free traversal; absent keys have no stored node row. */\n  getManyTopology?(keys: readonly Uint8Array[]): Promise<Map<string, NodeTopologyRecord>>;\n}\n\nfunction nodeTopology(value: unknown): NodeTopology | null {\n  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;\n  const row = value as Record<string, unknown>;\n  if ((row.kind !== 'atom' && row.kind !== 'fragment') || !Number.isSafeInteger(row.level) || (row.level as number) < 0) return null;\n  if (row.kind === 'atom') return { kind: row.kind, level: row.level as number };\n  if ((row.items != null && (!Array.isArray(row.items) || row.items.some(item => typeof item !== 'string')))\n    || (row.left != null && typeof row.left !== 'string') || (row.right != null && typeof row.right !== 'string')) return null;\n  return { kind: row.kind, level: row.level as number,\n    ...(row.items != null ? { items: row.items as string[] } : {}),\n    ...(row.left != null ? { left: row.left as string } : {}),\n    ...(row.right != null ? { right: row.right as string } : {}) };\n}\n\nexport const hex = (b: Uint8Array): string => Buffer.from(b.buffer, b.byteOffset, b.byteLength).toString('hex');\nexport const unhex = (h: string): Uint8Array => new Uint8Array(Buffer.from(h, 'hex'));\n\nexport function readerFromFdb(fdb: FdbLike, pageSize = 1000): KvReader {\n  return {\n    async scan(begin, end, onRow) {\n      let from = begin;\n      for (;;) {\n        const rows = await fdb.transact((txn) => txn.getRange(from, end, { limit: pageSize }));\n        for (const r of rows) onRow(r.key, r.value);\n        if (rows.length < pageSize) return;\n        // This is an exclusive cursor after ONE key, not a prefix-range end.\n        // strinc(last) skips every extension, including document ACL keys.\n        from = Uint8Array.from([...rows[rows.length - 1]!.key, 0]);\n      }\n    },\n    async getMany(keys) {\n      const out = new Map<string, Uint8Array>();\n      await fdb.transact(async (txn) => {\n        for (const k of keys) {\n          const v = await txn.get(k);\n          if (v !== undefined) out.set(hex(k), v);\n        }\n      });\n      return out;\n    },\n  };\n}\n\n/** A reader over a `pg` client (or pool); traversal fetches at most 32 nodes per query. */\nexport function readerFromPg(client: { query(sql: string, params?: unknown[]): Promise<{ rows: Array<{\n  k: Buffer; v?: Buffer; topology?: unknown; value_bytes?: unknown; needs_js_parse?: unknown; atom_header?: Buffer | null;\n}> }> }, table = 'pgsl_kv', pageSize = 5000, topologyBatchSize = TRAVERSAL_BATCH_SIZE): KvReader {\n  const t = table.replace(/[^a-zA-Z0-9_]/g, '');\n  if (!Number.isSafeInteger(topologyBatchSize) || topologyBatchSize < 1 || topologyBatchSize > 4096) throw new Error('invalid topology batch size');\n  return {\n    async scan(begin, end, onRow) {\n      let from = Buffer.from(begin);\n      const endBuf = Buffer.from(end);\n      for (;;) {\n        const r = await client.query(`SELECT k, v FROM ${t} WHERE k >= $1 AND k < $2 ORDER BY k LIMIT $3`, [from, endBuf, pageSize]);\n        for (const row of r.rows) {\n          if (!Buffer.isBuffer(row.v)) throw new Error('collector row value is unavailable');\n          onRow(new Uint8Array(row.k), new Uint8Array(row.v));\n        }\n        if (r.rows.length < pageSize) return;\n        from = Buffer.concat([r.rows[r.rows.length - 1]!.k, Buffer.from([0])]);\n      }\n    },\n    async getMany(keys) {\n      const out = new Map<string, Uint8Array>();\n      for (let i = 0; i < keys.length; i += 2000) {\n        const batch = keys.slice(i, i + 2000).map((k) => Buffer.from(k));\n        const r = await client.query(`SELECT k, v FROM ${t} WHERE k = ANY($1::bytea[])`, [batch]);\n        for (const row of r.rows) {\n          if (!Buffer.isBuffer(row.v)) throw new Error('collector row value is unavailable');\n          out.set(hex(new Uint8Array(row.k)), new Uint8Array(row.v));\n        }\n      }\n      return out;\n    },\n    async getManyTopology(keys) {\n      const out = new Map<string, NodeTopologyRecord>();\n      // Ordinary atom values/provenance stay in PostgreSQL. JSON's native\n      // parser rejects escapes that JS JSON.stringify can legitimately emit\n      // (NUL and lone surrogates), even in ignored values. Divert every raw\n      // backslash-u sequence before parsing and read only that exceptional row\n      // with the native JS semantics. This conservative discriminator can\n      // produce harmless false positives, without poisoning a rebuild's SQL\n      // transaction or exporting the rest of its 32-node batch.\n      // The default stays at 32. Private maintenance may probe atom prefixes in\n      // larger groups; fragment groups are sized with TOAST metadata first and\n      // limited to 8MiB of stored JSON, so a wide frontier stays memory-bounded.\n      const batches: Buffer[][] = [];\n      try {\n        if (topologyBatchSize <= TRAVERSAL_BATCH_SIZE) {\n          for (let i = 0; i < keys.length; i += topologyBatchSize) batches.push(keys.slice(i, i + topologyBatchSize).map(k => Buffer.from(k)));\n        } else {\n          const atoms = keys.filter(k => k[SUBSPACE_PAYLOAD_OFFSET] === 1);\n          for (let i = 0; i < atoms.length; i += topologyBatchSize) batches.push(atoms.slice(i, i + topologyBatchSize).map(k => Buffer.from(k)));\n          const fragments = keys.filter(k => k[SUBSPACE_PAYLOAD_OFFSET] !== 1);\n          let fragmentBytes = 0;\n          for (let i = 0; i < fragments.length; i += topologyBatchSize) {\n            const requested = fragments.slice(i, i + topologyBatchSize).map(k => Buffer.from(k));\n            const sizes = await client.query(`SELECT k,octet_length(v) AS value_bytes FROM ${t} WHERE k=ANY($1::bytea[]) ORDER BY k`, [requested]);\n            const wanted = new Set(requested.map(k => k.toString('hex')));\n            let group: Buffer[] = [], bytes = 0;\n            for (const row of sizes.rows) {\n              if (!Buffer.isBuffer(row.k) || !wanted.delete(row.k.toString('hex')) || !Number.isSafeInteger(row.value_bytes)\n                || (row.value_bytes as number) < 0 || (row.value_bytes as number) > 8 * 1024 * 1024) throw new Error('unbounded fragment topology');\n              fragmentBytes += row.value_bytes as number;\n              if (fragmentBytes > 64 * 1024 * 1024) throw new Error('unbounded fragment frontier');\n              if (group.length && bytes + (row.value_bytes as number) > 8 * 1024 * 1024) {\n                batches.push(group); group = []; bytes = 0;\n              }\n              group.push(row.k); bytes += row.value_bytes as number;\n            }\n            if (group.length) batches.push(group);\n          }\n        }\n      } catch {\n        throw new Error('refusing collection: PostgreSQL node topology could not be read');\n      }\n      for (const batch of batches) {\n        try {\n          const result = await client.query(`SELECT source.k, octet_length(source.v) AS value_bytes,\n              substring(source.v FROM 1 FOR ${ATOM_HEADER_BYTES}) AS atom_header,\n              false AS needs_js_parse, NULL::json AS topology\n            FROM ${t} AS source\n            WHERE source.k = ANY($1::bytea[]) AND get_byte(source.k, ${SUBSPACE_PAYLOAD_OFFSET}) = 1\n            UNION ALL\n            SELECT source.k, octet_length(source.v) AS value_bytes, NULL::bytea AS atom_header,\n              position(decode('5c75', 'hex') in source.v) > 0 AS needs_js_parse,\n              json_build_object('uri', n.uri, 'kind', n.kind, 'level', n.level,\n                'items', CASE WHEN n.kind #>> '{}' = 'fragment' THEN n.items END,\n                'left', CASE WHEN n.kind #>> '{}' = 'fragment' THEN n.\"left\" END,\n                'right', CASE WHEN n.kind #>> '{}' = 'fragment' THEN n.\"right\" END) AS topology\n            FROM ${t} AS source\n            CROSS JOIN LATERAL json_to_record(CASE\n              WHEN position(decode('5c75', 'hex') in source.v) > 0 THEN '{}'::json\n              ELSE convert_from(source.v, 'UTF8')::json END)\n              AS n(uri text, kind json, level json, items json, \"left\" json, \"right\" json)\n            WHERE source.k = ANY($1::bytea[]) AND get_byte(source.k, ${SUBSPACE_PAYLOAD_OFFSET}) <> 1`, [batch]);\n          for (const row of result.rows) {\n            if (!Buffer.isBuffer(row.k) || !Number.isSafeInteger(row.value_bytes) || (row.value_bytes as number) < 0\n              || typeof row.needs_js_parse !== 'boolean') {\n              throw new Error('invalid topology record');\n            }\n            if (!row.needs_js_parse && row.topology && typeof row.topology === 'object' && 'uri' in row.topology) {\n              const storedUri = (row.topology as { uri?: unknown }).uri;\n              if (typeof storedUri !== 'string' || !row.k.equals(Buffer.from(nodeKey(nodeAddrFromUrn(storedUri))))) throw new Error('node body/key binding changed');\n            }\n            let topology: NodeTopology | null;\n            const atomTopology = row.atom_header === null || row.atom_header === undefined ? null\n              : atomTopologyFromPrefix(new Uint8Array(row.k), new Uint8Array(row.atom_header), row.value_bytes as number);\n            if (atomTopology) topology = atomTopology;\n            else if (row.needs_js_parse || row.atom_header !== null && row.atom_header !== undefined) {\n              const exceptional = await client.query(`SELECT k, v FROM ${t} WHERE k = ANY($1::bytea[])`, [[row.k]]);\n              const value = exceptional.rows[0];\n              if (exceptional.rows.length !== 1 || !value || !Buffer.isBuffer(value.k) || !value.k.equals(row.k)\n                || !Buffer.isBuffer(value.v) || value.v.length !== row.value_bytes) throw new Error('invalid exceptional topology record');\n              const decoded = JSON.parse(nodeDec.decode(value.v)) as StoredNode;\n              if (!value.k.equals(Buffer.from(nodeKey(nodeAddrFromUrn(decoded.uri))))) throw new Error('node body/key binding changed');\n              topology = nodeTopology(decoded);\n            } else topology = nodeTopology(row.topology);\n            out.set(hex(new Uint8Array(row.k)), { topology, byteLength: row.value_bytes as number });\n          }\n        } catch {\n          // PostgreSQL JSON/UTF8 error details can include private payload bytes.\n          // No caller receives that error or its cause, and no incomplete scan\n          // may advance to retirement or rebuilding.\n          throw new Error('refusing collection: PostgreSQL node topology could not be read');\n        }\n      }\n      return out;\n    },\n  };\n}\n\nexport interface CollectStats {\n  /** Rows kept per subspace. */\n  readonly kept: Record<SubspaceTag, number>;\n  /** Rows seen in the subspaces that were scanned (N, I, B, L and R are not scanned). */\n  readonly scanned: Partial<Record<SubspaceTag, number>>;\n  readonly roots: number;\n  readonly liveNodes: number;\n  readonly liveAtoms: number;\n  readonly liveFragments: number;\n  /** Bytes of live node values, the size the live table will roughly have before compression. */\n  readonly liveNodeBytes: number;\n  /** Root URNs whose node row does not exist: a record pointing at nothing, reported, never fatal. */\n  readonly danglingRoots: string[];\n  /** Nodes whose value could not be parsed; kept, with their reconstructed rows, on the safe side. */\n  readonly unreadableNodes: number;\n  /** O rows whose resource record is gone: deleted resources whose overlay row was never cleared. */\n  readonly staleOverlays: number;\n}\n\nexport interface LiveSet {\n  /** Every key to keep, hex-encoded, in no particular order. */\n  readonly keys: Set<string>;\n  readonly stats: CollectStats;\n}\n\nfunction addrOfBytes(b: Uint8Array): NodeAddr {\n  const kind: NodeKind = b[0] === kindByte('fragment') ? 'fragment' : 'atom';\n  return { kind, hash: b.slice(1, 1 + HASH_BYTES) };\n}\n\nfunction urnsIn(value: unknown, out: Set<string>): void {\n  if (typeof value === 'string') { if (isNodeIdentifier(value)) out.add(value); return; }\n  if (Array.isArray(value)) { for (const v of value) urnsIn(v, out); return; }\n  if (value && typeof value === 'object') for (const v of Object.values(value as Record<string, unknown>)) urnsIn(v, out);\n}\n\n/**\n * Compute the live set. Reads only. Runs in memory proportional to the live set plus the\n * scanned subspaces' keys, which on the production store is a few million short keys.\n */\nexport async function collectLive(reader: KvReader, opts: { readonly log?: (line: string) => void; readonly traversalBatchSize?: number } = {}): Promise<LiveSet> {\n  const log = opts.log ?? (() => undefined);\n  const traversalBatchSize = opts.traversalBatchSize ?? TRAVERSAL_BATCH_SIZE;\n  if (!Number.isSafeInteger(traversalBatchSize) || traversalBatchSize < 1 || traversalBatchSize > 4096) throw new Error('invalid traversal batch size');\n  const keys = new Set<string>();\n  const kept: Record<SubspaceTag, number> = { N: 0, I: 0, B: 0, L: 0, R: 0, V: 0, O: 0, W: 0, P: 0, A: 0, X: 0, C: 0 };\n  const scanned: Partial<Record<SubspaceTag, number>> = {};\n  const roots = new Set<string>();           // node URNs\n  const rootAddrs = new Set<string>();       // hex of 21-byte addresses (from A, X, P keys)\n  const keep = (tag: SubspaceTag, k: Uint8Array): void => { keys.add(hex(k)); kept[tag] += 1; };\n\n  // Mutable subspaces: kept whole, and mined for roots.\n  const controlKeys = new Set<string>();\n  await reader.scan(subspaceRange('C').begin, subspaceRange('C').end, (k, v) => {\n    scanned.C = (scanned.C ?? 0) + 1;\n    keep('C', k);\n    controlKeys.add(hex(k));\n    try { urnsIn(JSON.parse(dec.decode(v)), roots); } catch { /* not JSON: a record we keep but cannot mine */ }\n  });\n  // O rows are written by LdpStore beside the resource's C record and were never cleared on\n  // delete, so an O row whose C record is gone is the ghost of a deleted resource: it is not\n  // kept and does not root anything. An O row whose key cannot be read as (pod, resource) is\n  // kept and rooted, on the safe side.\n  let staleOverlays = 0;\n  await reader.scan(subspaceRange('O').begin, subspaceRange('O').end, (k, v) => {\n    scanned.O = (scanned.O ?? 0) + 1;\n    const payload = k.slice(SUBSPACE_PAYLOAD_OFFSET);\n    const sep = payload.indexOf(0);\n    if (sep > 0) {\n      const pod = dec.decode(payload.slice(0, sep));\n      const resource = dec.decode(payload.slice(sep + 1));\n      if (!controlKeys.has(hex(cpKey(`ldp ${pod}`, resource)))) { staleOverlays += 1; return; }\n    }\n    keep('O', k);\n    const urn = dec.decode(v);\n    if (isNodeIdentifier(urn)) roots.add(urn);\n  });\n  for (const tag of ['A', 'X'] as const) {\n    await reader.scan(subspaceRange(tag).begin, subspaceRange(tag).end, (k) => {\n      scanned[tag] = (scanned[tag] ?? 0) + 1;\n      keep(tag, k);\n      rootAddrs.add(hex(k.slice(k.length - ADDR_BYTES)));\n    });\n  }\n  // P: tier-2 rows are derived (one per composed node) and follow their node; any other tier is a root.\n  const pRows: Array<{ key: Uint8Array; addr: string }> = [];\n  await reader.scan(subspaceRange('P').begin, subspaceRange('P').end, (k) => {\n    scanned.P = (scanned.P ?? 0) + 1;\n    const addr = hex(k.slice(SUBSPACE_PAYLOAD_OFFSET, SUBSPACE_PAYLOAD_OFFSET + ADDR_BYTES));\n    const tier = k.length >= SUBSPACE_PAYLOAD_OFFSET + ADDR_BYTES + 4 ? new DataView(k.buffer, k.byteOffset + k.length - 4, 4).getUint32(0) : -1;\n    if (tier !== 2) { rootAddrs.add(addr); keep('P', k); }\n    else pRows.push({ key: k, addr });\n  });\n  log(`roots: ${roots.size} URNs from C/O, ${rootAddrs.size} addresses from A/X/P; C ${scanned.C ?? 0}, O ${scanned.O ?? 0}, P ${scanned.P ?? 0} rows`);\n\n  // Traverse.\n  const live = new Map<string, { addr: NodeAddr; node: NodeTopology | null }>(); // hex addr -> node\n  const dangling: string[] = [];\n  let unreadable = 0;\n  let liveNodeBytes = 0;\n  const frontier: NodeAddr[] = [];\n  const enqueue = (addr: NodeAddr): void => { const h = hex(nodeAddrBytes(addr)); if (!live.has(h)) { live.set(h, { addr, node: null }); frontier.push(addr); } };\n  for (const urn of roots) { try { enqueue(nodeAddrFromUrn(urn)); } catch { dangling.push(urn); } }\n  for (const a of rootAddrs) enqueue(addrOfBytes(unhex(a)));\n  let frontierOffset = 0;\n  while (frontierOffset < frontier.length) {\n    // Shifting a six-figure frontier once per 32 nodes is quadratic work.\n    // A cursor plus occasional compaction preserves order with bounded storage.\n    const batch = frontier.slice(frontierOffset, frontierOffset + traversalBatchSize);\n    frontierOffset += batch.length;\n    const batchKeys = batch.map(a => nodeKey(a));\n    const values = reader.getManyTopology ? await reader.getManyTopology(batchKeys) : await reader.getMany(batchKeys);\n    for (const addr of batch) {\n      const k = nodeKey(addr);\n      const v = values.get(hex(k));\n      const h = hex(nodeAddrBytes(addr));\n      if (v === undefined) { dangling.push(`urn:pgsl:${addr.kind}:${hex(addr.hash)}`); live.delete(h); continue; }\n      let node: NodeTopology | null = null;\n      if (v instanceof Uint8Array) {\n        liveNodeBytes += v.length;\n        try { node = nodeTopology(JSON.parse(nodeDec.decode(v))); } catch { /* unreadable below */ }\n      } else {\n        if (!Number.isSafeInteger(v.byteLength) || v.byteLength < 0) throw new Error('refusing collection: invalid topology byte count');\n        liveNodeBytes += v.byteLength;\n        node = nodeTopology(v.topology);\n      }\n      if (!node || node.kind !== addr.kind) { node = null; unreadable += 1; }\n      // Release fetched bytes as each node is consumed, not at the next batch.\n      values.delete(hex(k));\n      live.set(h, { addr, node });\n      if (node?.kind === 'fragment') {\n        for (const item of node.items ?? []) { try { enqueue(nodeAddrFromUrn(item)); } catch { /* not a node urn */ } }\n        for (const side of [node.left, node.right]) if (side) { try { enqueue(nodeAddrFromUrn(side)); } catch { /* not a node urn */ } }\n      }\n    }\n    log(`traversed ${live.size} live nodes, frontier ${frontier.length - frontierOffset}`);\n    if (frontierOffset >= 16_384) {\n      frontier.splice(0, frontierOffset);\n      frontierOffset = 0;\n    }\n  }\n\n  // Reconstruct the rows compose() wrote for each live node.\n  let liveAtoms = 0;\n  let liveFragments = 0;\n  const liveHashes = new Set<string>();\n  for (const { addr, node } of live.values()) {\n    liveHashes.add(hex(addr.hash));\n    keep('N', nodeKey(addr));\n    if (node) keep('V', lvKey(node.level, addr));\n    if (addr.kind === 'atom') liveAtoms += 1; else liveFragments += 1;\n    if (node?.kind === 'fragment') {\n      (node.items ?? []).forEach((itemUri, pos) => {\n        let itemAddr: NodeAddr;\n        try { itemAddr = nodeAddrFromUrn(itemUri); } catch { return; }\n        keep('I', ciKey(addr.hash, pos));\n        keep('B', cbKey(itemAddr, addr.hash));\n      });\n      if (node.left) { try { keep('L', lftKey(nodeAddrFromUrn(node.left).hash, addr.hash)); } catch { /* skip */ } }\n      if (node.right) { try { keep('R', rgtKey(nodeAddrFromUrn(node.right).hash, addr.hash)); } catch { /* skip */ } }\n    }\n  }\n  // V rows for nodes whose level could not be read: keep every V row of a live address.\n  await reader.scan(subspaceRange('V').begin, subspaceRange('V').end, (k) => {\n    scanned.V = (scanned.V ?? 0) + 1;\n    const addr = hex(k.slice(k.length - ADDR_BYTES));\n    if (live.has(addr) && !keys.has(hex(k))) keep('V', k);\n  });\n  for (const p of pRows) if (live.has(p.addr)) keep('P', p.key);\n  for (const { addr } of live.values()) { const k = prKey(addr, 2); if (!keys.has(hex(k))) keep('P', k); }\n  await reader.scan(subspaceRange('W').begin, subspaceRange('W').end, (k) => {\n    scanned.W = (scanned.W ?? 0) + 1;\n    const top = hex(k.slice(SUBSPACE_PAYLOAD_OFFSET, SUBSPACE_PAYLOAD_OFFSET + HASH_BYTES));\n    if (liveHashes.has(top)) keep('W', k);\n  });\n  const stats: CollectStats = {\n    kept, scanned, roots: roots.size + rootAddrs.size, liveNodes: live.size, liveAtoms, liveFragments, liveNodeBytes,\n    danglingRoots: dangling, unreadableNodes: unreadable, staleOverlays,\n  };\n  log(`live set: ${keys.size} keys, ${live.size} nodes (${liveAtoms} atoms, ${liveFragments} fragments), ${(liveNodeBytes / 1048576).toFixed(1)} MB of node values, ${dangling.length} dangling roots, ${staleOverlays} stale overlay rows`);\n  return { keys, stats };\n}\n\n/** Group the live keys by subspace, for reporting and for copying range by range. */\nexport function keysBySubspace(keys: ReadonlySet<string>): Record<string, number> {\n  const out: Record<string, number> = {};\n  for (const k of keys) {\n    const tag = String.fromCharCode(parseInt(k.slice(SUBSPACE_PAYLOAD_OFFSET * 2 - 2, SUBSPACE_PAYLOAD_OFFSET * 2), 16));\n    out[tag] = (out[tag] ?? 0) + 1;\n  }\n  return out;\n}\n\nexport interface RebuildResult {\n  readonly copied: number;\n  readonly oldTable: string;\n  readonly newRows: number;\n}\n\n/** Optional compaction was deferred; the original table remains authoritative. */\nexport class RebuildDeferredError extends Error {\n  readonly code = 'REBUILD_DEFERRED';\n  constructor(readonly reason: 'sql-work-budget' | 'lock-unavailable') {\n    super(`rebuild deferred: ${reason === 'sql-work-budget' ? 'SQL work budget exhausted' : 'live table is busy'}; compaction is not confirmed`);\n    this.name = 'RebuildDeferredError';\n  }\n}\n\n/**\n * The storage parameters of `from`, applied to `to`: `CREATE TABLE ... (LIKE ... INCLUDING ALL)`\n * copies columns, constraints, indexes and column storage, but no relation options, so the\n * autovacuum settings `--tune` put on the table and its TOAST relation would vanish with every\n * rebuild and the table would drift back to the defaults that let it reach 45 GB. Options are\n * read from the catalog and applied as they are; anything not of the form name=value is\n * skipped and named. Returns what was applied.\n */\nexport async function copyStorageParameters(\n  client: { query(sql: string, params?: unknown[]): Promise<{ rows: Array<Record<string, unknown>> }> },\n  from: string,\n  to: string,\n  log: (line: string) => void = () => undefined,\n): Promise<string[]> {\n  const r = await client.query('SELECT c.reloptions AS heap, tc.reloptions AS toast FROM pg_class c LEFT JOIN pg_class tc ON tc.oid = c.reltoastrelid WHERE c.oid = $1::regclass', [from]);\n  const asList = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : []);\n  const wellFormed = /^[a-z_]+=[A-Za-z0-9_.-]+$/;\n  const heap = asList(r.rows[0]?.['heap']);\n  const toast = asList(r.rows[0]?.['toast']);\n  const skipped = [...heap, ...toast].filter((o) => !wellFormed.test(o));\n  if (skipped.length > 0) log(`storage parameters not carried over (not name=value): ${skipped.join(', ')}`);\n  const heapOk = heap.filter((o) => wellFormed.test(o));\n  const toastOk = toast.filter((o) => wellFormed.test(o)).map((o) => `toast.${o}`);\n  if (heapOk.length > 0) await client.query(`ALTER TABLE ${to} SET (${heapOk.join(', ')})`);\n  if (toastOk.length > 0) await client.query(`ALTER TABLE ${to} SET (${toastOk.join(', ')})`);\n  const applied = [...heapOk, ...toastOk];\n  if (applied.length > 0) log(`storage parameters carried over to ${to}: ${applied.join(', ')}`);\n  return applied;\n}\n/**\n * Copy the live rows into a fresh table and swap it in, inside one transaction that holds an\n * ACCESS EXCLUSIVE lock on the old table: every other session waits until commit or rollback.\n * The exact live set is computed INSIDE that lock. The entire SQL work has a five-second\n * monotonic budget with a server statement timeout for each remaining slice. PostgreSQL 16\n * cannot interrupt durable COMMIT, so the deadline is checked before dispatch but is not an\n * absolute lock-hold guarantee. This is not online compaction or guaranteed reclamation.\n */\nexport function rebuildOldTableSuffix(now = new Date()): string {\n  const stamp = now.toISOString().replace(/[-:.TZ]/g, '');\n  return `old_${stamp.slice(0, 8)}_${stamp.slice(8)}`;\n}\n\n/** Serialize collectors before PostgreSQL resolves the live relation's OID.\n * A waiter on LOCK TABLE alone can acquire the renamed backup after another\n * collector swaps it, then accidentally collect the new live table unlocked.\n * Session advisory locks also cover CLI measurement/drop and are reentrant when\n * that same session calls rebuildTable. A lost connection releases the lock. */\nexport async function acquireCollectorLock(\n  client: { query(sql: string, params?: unknown[]): Promise<{ rows: Array<Record<string, unknown>> }> },\n  table: string,\n): Promise<() => Promise<void>> {\n  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(table)) throw new Error('invalid collector table name');\n  const key = table.toLowerCase();\n  const acquired = await client.query(\"SELECT pg_try_advisory_lock(hashtextextended(current_database() || ':public.' || $1, 0)) AS acquired\", [key]);\n  if (acquired.rows[0]?.['acquired'] !== true) throw new Error('refusing concurrent collector: another collector holds this database/table lock');\n  let released = false;\n  return async () => {\n    if (released) return;\n    const result = await client.query(\"SELECT pg_advisory_unlock(hashtextextended(current_database() || ':public.' || $1, 0)) AS released\", [key]);\n    if (result.rows[0]?.['released'] !== true) throw new Error('collector advisory lock release was not confirmed');\n    released = true;\n  };\n}\n\nexport async function rebuildTable(\n  client: { query(sql: string, params?: unknown[]): Promise<{ rows: Array<Record<string, unknown>>; rowCount: number | null }> },\n  table: string,\n  opts: { readonly log?: (line: string) => void; readonly batch?: number; readonly suffixOld?: string;\n    /** Tests or a stricter caller may lower, but never lengthen, the live SQL work budget. */\n    readonly sqlWorkBudgetMs?: number } = {},\n): Promise<RebuildResult> {\n  const t = table.replace(/[^a-zA-Z0-9_]/g, '');\n  const oldTable = `${t}_${opts.suffixOld ?? rebuildOldTableSuffix()}`;\n  const newTable = `${t}_live`;\n  const batch = opts.batch ?? 4000;\n  const log = opts.log ?? (() => undefined);\n  const budget = opts.sqlWorkBudgetMs ?? 5000;\n  if (!Number.isSafeInteger(budget) || budget < 1 || budget > 5000) throw new Error('collector SQL work budget must be between 1 and 5000 milliseconds');\n  const release = await acquireCollectorLock(client, t);\n  let failure: unknown;\n  try {\n    // PostgreSQL 16 has no transaction_timeout. On newer servers, use its\n    // independent backstop in addition to the remaining-statement budget.\n    const setting = await client.query(\"SELECT current_setting('transaction_timeout', true) AS transaction_timeout\");\n    const hasTransactionTimeout = typeof setting.rows[0]?.['transaction_timeout'] === 'string';\n    const deadline = performance.now() + budget;\n    let deferred: RebuildDeferredError | undefined;\n    const remaining = (): number => {\n      const ms = Math.floor(deadline - performance.now());\n      if (ms < 1) { deferred ??= new RebuildDeferredError('sql-work-budget'); throw deferred; }\n      return ms;\n    };\n    const bounded = { async query(sql: string, params?: unknown[]) {\n      const allowance = remaining();\n      try {\n        // A client-side query_timeout does not cancel PostgreSQL work. Use the\n        // server's timeout, reduced before EVERY query while the lock is held.\n        await client.query(`SET LOCAL statement_timeout = '${allowance}ms'`);\n        remaining();\n        const result = await client.query(sql, params);\n        // An acknowledged commit already released the lock and must never be\n        // reported as rolled back just because its reply crossed the deadline.\n        if (sql !== 'COMMIT') remaining();\n        return result;\n      } catch (error) {\n        const code = error !== null && typeof error === 'object' ? (error as { code?: string }).code : undefined;\n        if (code === '57014') deferred ??= new RebuildDeferredError('sql-work-budget');\n        if (code === '55P03') deferred ??= new RebuildDeferredError('lock-unavailable');\n        throw deferred ?? error;\n      }\n    } };\n    await client.query('BEGIN');\n    try {\n      // A stalled collector must not retain its transaction while waiting for\n      // another client query. This setting is local to this maintenance attempt.\n      await bounded.query(\"SET LOCAL idle_in_transaction_session_timeout = '1s'\");\n      if (hasTransactionTimeout) await bounded.query(`SET LOCAL transaction_timeout = '${remaining()}ms'`);\n      // ACCESS EXCLUSIVE from the start, not EXCLUSIVE upgraded at the rename: with EXCLUSIVE held,\n      // a store transaction that had already read (ACCESS SHARE) and now waited to write blocked on\n      // this transaction, whose RENAME then waited on that reader's ACCESS SHARE, and Postgres\n      // resolved the cycle by killing the rebuild after the copy (measured on the first production\n      // run, 2026-09-20). Take the strongest lock without queuing, then keep the traversal and\n      // copy within the short budget; no lock upgrade can form that cycle.\n      await bounded.query(`LOCK TABLE ${t} IN ACCESS EXCLUSIVE MODE NOWAIT`);\n      log('lock held for a budgeted maintenance attempt; readers and writers resume on commit or rollback');\n      const live = await collectLive(readerFromPg(bounded as never, t), { log });\n      remaining();\n      if (live.keys.size === 0) throw new Error('refusing to rebuild: the live set is empty');\n      // A missing or unreadable retained node makes reachability incomplete.\n      // Preserve the existing table rather than collecting through uncertainty.\n      if (live.stats.danglingRoots.length > 0 || live.stats.unreadableNodes > 0) {\n        throw new Error(`refusing to rebuild: ${live.stats.danglingRoots.length} dangling roots and ${live.stats.unreadableNodes} unreadable nodes`);\n      }\n      await bounded.query(`CREATE TABLE ${newTable} (LIKE ${t} INCLUDING ALL)`);\n      await copyStorageParameters(bounded, t, newTable, log);\n      const all = [...live.keys];\n      let copied = 0;\n      for (let i = 0; i < all.length; i += batch) {\n        const chunk = all.slice(i, i + batch).map((h) => Buffer.from(h, 'hex'));\n        const r = await bounded.query(`INSERT INTO ${newTable} (k, v) SELECT k, v FROM ${t} WHERE k = ANY($1::bytea[]) ON CONFLICT DO NOTHING`, [chunk]);\n        copied += r.rowCount ?? 0;\n        if ((i / batch) % 25 === 0) log(`copied ${copied} of up to ${all.length} rows`);\n      }\n      const count = await bounded.query(`SELECT count(*)::bigint AS n FROM ${newTable}`);\n      const newRows = Number(count.rows[0]?.['n'] ?? 0);\n      // Reconstructed keys are promises of retained data. Both the INSERT row\n      // counts and an independent table count must confirm every promised key.\n      if (copied !== live.keys.size || newRows !== live.keys.size) {\n        throw new Error(`refusing to swap: expected ${live.keys.size} live keys, copied ${copied}, counted ${newRows}`);\n      }\n      await bounded.query(`ALTER TABLE ${t} RENAME TO ${oldTable}`);\n      await bounded.query(`ALTER TABLE ${newTable} RENAME TO ${t}`);\n      await bounded.query('COMMIT');\n      log(`swapped: ${t} now has ${newRows} rows; the previous table is ${oldTable}`);\n      return { copied, oldTable, newRows };\n    } catch (err) {\n      // Deliberately bypass the exhausted query wrapper so PostgreSQL releases\n      // the lock and rolls back any partially copied table or rename.\n      await client.query('ROLLBACK').catch(() => undefined);\n      throw deferred ?? err;\n    }\n  } catch (error) {\n    failure = error;\n    throw error;\n  } finally {\n    // A transaction/idle timeout on supported servers terminates the session,\n    // which already releases its advisory lock. Preserve the original failure.\n    if (failure) await release().catch(() => undefined);\n    else await release();\n  }\n}\n","volume.mjs":"/** Resolve only the database volume mounted in the token's exact environment.\n * Ambiguous instance lists are refused instead of borrowing another environment's space. */\nexport function collectorVolumeHeadroom(data, serviceId, sampledAt = Date.now()) {\n  const config = typeof data?.environment?.config === 'string' ? JSON.parse(data.environment.config) : data?.environment?.config;\n  const mounts = config?.services?.[serviceId]?.volumeMounts;\n  const candidates = [];\n  for (const { node: volume } of data?.project?.volumes?.edges ?? []) {\n    if (!mounts?.[volume.id]) continue;\n    for (const { node: instance } of volume.volumeInstances?.edges ?? []) {\n      if (instance.serviceId === serviceId && instance.mountPath === mounts[volume.id].mountPath) candidates.push(instance);\n    }\n  }\n  if (candidates.length !== 1) throw new Error('refusing collector copy: exact environment database volume is missing or ambiguous');\n  const { sizeMB, currentSizeMB } = candidates[0];\n  if (!Number.isFinite(sizeMB) || sizeMB <= 0 || !Number.isFinite(currentSizeMB) || currentSizeMB < 0 || currentSizeMB > sizeMB\n    || !Number.isSafeInteger(sampledAt)) throw new Error('refusing collector copy: database volume usage is unavailable');\n  // Capacity is rounded down in decimal MB and usage up in binary MB. This\n  // deliberately understates free space under either common MB convention.\n  return { capacityBytes: Math.floor(sizeMB * 1_000_000), usedBytes: Math.ceil(currentSizeMB * 1_048_576), sampledAt };\n}\n","sweep.mjs":"/**\n * Private, bounded in-place PGSL reclamation. Run inside the database's Railway\n * project; no database TCP proxy or public row transfer is used.\n * Install once AFTER migration validation, then schedule this process hourly.\n * Keeps every current root and every root retired in the preceding hour.\n * DELETE + ordinary VACUUM makes pages reusable; it does not shrink the volume.\n */\nimport { pathToFileURL } from 'node:url';\nimport { Client } from 'pg@8.22.0';\nimport { acquireCollectorLock, collectLive, readerFromPg } from './gc.ts';\nimport { nodeAddrFromUrn } from './addressing.ts';\nimport { SUBSPACE_PAYLOAD_OFFSET } from './keyspace.ts';\nimport { collectorVolumeHeadroom } from './volume.mjs';\n\nconst HOUR = 3_600_000, GiB = 1_073_741_824;\nconst utf8 = new TextDecoder('utf-8', { fatal: true });\nconst rootTags = new Set(['C', 'O', 'A', 'X', 'P']);\nfunction names(table) {\n  if (!/^[a-z_][a-z0-9_]{0,39}$/.test(table)) throw Error('refusing sweep: invalid table name');\n  return { table, relation: 'public.' + table, roots: 'public.' + table + '_gc_roots',\n    state: 'public.' + table + '_gc_state', fn: 'public.' + table + '_gc_remember_roots',\n    trigger: table + '_gc_root_history' };\n}\nfunction triggerBody(n) {\n  return `\nBEGIN\n  IF TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> '${n.table}' THEN\n    RAISE EXCEPTION 'invalid root journal trigger target';\n  END IF;\n  -- Exclude immutable node/index keys before inspecting NEW.v: a node can be a\n  -- 38MiB TOAST value, and journaling it must not detoast or compare its body.\n  IF octet_length(OLD.k) >= 6 AND substring(OLD.k FROM 1 FOR 5) = decode('7067736c00','hex')\n     AND (get_byte(OLD.k,5) IN (67,79,65,88) OR\n       (get_byte(OLD.k,5) = 80 AND\n        (octet_length(OLD.k) <> 31 OR substring(OLD.k FROM 28 FOR 4) <> decode('00000002','hex')))) THEN\n    IF TG_OP = 'DELETE' OR NEW.k IS DISTINCT FROM OLD.k OR NEW.v IS DISTINCT FROM OLD.v THEN\n      INSERT INTO ${n.roots}(k,v,retired_at) VALUES(OLD.k,OLD.v,clock_timestamp());\n    END IF;\n  END IF;\n  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND\n`;\n}\nasync function verifyJournal(client, n) {\n  const r = await client.query(`SELECT t.tgenabled,p.prosrc,p.prosecdef,p.proconfig,t.tgtype,\n      t.tgrelid = to_regclass($1) AS correct_relation\n    FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid\n    WHERE t.tgname=$2 AND t.tgrelid=to_regclass($1) AND NOT t.tgisinternal`,\n    [n.relation,n.trigger]);\n  const row = r.rows[0];\n  if (r.rows.length !== 1 || row.tgenabled !== 'A' || !row.correct_relation || !row.prosecdef || row.tgtype !== 25\n    || JSON.stringify(row.proconfig) !== JSON.stringify(['search_path=pg_catalog']) || row.prosrc !== triggerBody(n)) {\n    throw Error('refusing sweep: the continuously enabled root journal is not verified');\n  }\n}\nexport async function installSweep(client, { table = 'pgsl_kv' } = {}) {\n  const n = names(table), release = await acquireCollectorLock(client, table);\n  try {\n    await client.query('BEGIN');\n    await client.query(`LOCK TABLE ${n.relation} IN SHARE ROW EXCLUSIVE MODE NOWAIT`);\n    const prior = await client.query('SELECT to_regclass($1) AS existing', [n.state]);\n    if (prior.rows[0].existing) await verifyJournal(client,n);\n    await client.query(`CREATE TABLE IF NOT EXISTS ${n.state}\n      (singleton boolean PRIMARY KEY CHECK(singleton), installed_at timestamptz NOT NULL)`);\n    await client.query(`CREATE TABLE IF NOT EXISTS ${n.roots}\n      (k bytea NOT NULL,v bytea NOT NULL,retired_at timestamptz NOT NULL)`);\n    await client.query(`CREATE INDEX IF NOT EXISTS ${table}_gc_roots_time ON ${n.roots}(retired_at)`);\n    await client.query(`REVOKE ALL ON ${n.roots},${n.state} FROM PUBLIC`);\n    await client.query(`CREATE OR REPLACE FUNCTION ${n.fn}() RETURNS trigger\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $root_history$${triggerBody(n)}$root_history$`);\n    await client.query(`DROP TRIGGER IF EXISTS ${n.trigger} ON ${n.relation}`);\n    await client.query(`CREATE TRIGGER ${n.trigger} AFTER UPDATE OR DELETE ON ${n.relation}\n      FOR EACH ROW EXECUTE FUNCTION ${n.fn}()`);\n    await client.query(`ALTER TABLE ${n.relation} ENABLE ALWAYS TRIGGER ${n.trigger}`);\n    await client.query(`INSERT INTO ${n.state}(singleton,installed_at) VALUES(true,clock_timestamp())\n      ON CONFLICT(singleton) DO NOTHING`);\n    await client.query('COMMIT');\n  } catch (error) {\n    await client.query('ROLLBACK').catch(()=>{});\n    throw error;\n  } finally { await release(); }\n}\nfunction validateIdentifier(text) {\n  try { nodeAddrFromUrn(text); } catch { throw Error('refusing sweep: malformed retained node identifier'); }\n}\nfunction validateJsonRoots(value) {\n  if (typeof value === 'string') {\n    if (value.startsWith('urn:pgsl:') || value.includes('/ns/pgsl/')) validateIdentifier(value);\n  } else if (Array.isArray(value)) for (const child of value) validateJsonRoots(child);\n  else if (value && typeof value === 'object') for (const child of Object.values(value)) validateJsonRoots(child);\n}\nfunction validateRoot(key,value) {\n  const tag = String.fromCharCode(key[SUBSPACE_PAYLOAD_OFFSET-1]);\n  try {\n    if (tag === 'C') {\n      if (value.length > 1_048_576 || key.subarray(SUBSPACE_PAYLOAD_OFFSET).indexOf(0) < 0) throw Error();\n      validateJsonRoots(JSON.parse(utf8.decode(value)));\n    } else if (tag === 'O') {\n      if (value.length > 8192 || key.subarray(SUBSPACE_PAYLOAD_OFFSET).indexOf(0) < 0) throw Error();\n      validateIdentifier(utf8.decode(value));\n    } else {\n      const address = tag === 'P' ? key.subarray(SUBSPACE_PAYLOAD_OFFSET,SUBSPACE_PAYLOAD_OFFSET+21) : key.subarray(key.length-21);\n      if (address.length !== 21 || (address[0] !== 1 && address[0] !== 2)) throw Error();\n      if (tag === 'P' && key.length !== SUBSPACE_PAYLOAD_OFFSET+25) throw Error();\n      if (tag === 'A' && (key.length < 28 || key[key.length-22] !== 0)) throw Error();\n      if (tag === 'X' && (key.length < 32 || key[key.length-26] !== 0)) throw Error();\n    }\n  } catch { throw Error('refusing sweep: corrupt or unsupported mutable root'); }\n}\n/** Add all versions retired within the rollback window to the same root scan. */\nfunction retainedReader(client,n,cutoff,check) {\n  const base = readerFromPg(client,n.table,5000,4096);\n  return {\n    ...base,\n    async scan(begin,end,onRow) {\n      const tag=String.fromCharCode(begin[SUBSPACE_PAYLOAD_OFFSET-1]);\n      const consume=(k,v)=>{ check(); if(rootTags.has(tag))validateRoot(k,v); onRow(k,v); };\n      await base.scan(begin,end,consume);\n      if (!rootTags.has(tag)) return;\n      // A cursor uses (retired_at,ctid) only within the fenced transaction;\n      // no writer can change the journal until this transaction releases its fence.\n      let cursor=null;\n      for (;;) {\n        check();\n        const rows=await client.query(`SELECT k,v,retired_at::text AS cursor_time,ctid::text AS row_id FROM ${n.roots}\n          WHERE retired_at >= $1 AND k >= $2 AND k < $3\n          AND ($4::timestamptz IS NULL OR (retired_at,ctid) > ($4::timestamptz,$5::tid))\n          ORDER BY retired_at,ctid LIMIT 1000`,[cutoff,Buffer.from(begin),Buffer.from(end),cursor?.cursor_time??null,cursor?.row_id??null]);\n        for(const row of rows.rows)consume(row.k,row.v);\n        if(rows.rows.length<1000)break;\n        cursor=rows.rows.at(-1);\n      }\n    },\n    async getManyTopology(keys) {\n      check();\n      const records=await base.getManyTopology(keys);\n      for(const row of records.values()) {\n        if(!row.topology)throw Error('refusing sweep: unreadable retained node');\n        if(row.topology.kind==='fragment') {\n          for(const uri of [...(row.topology.items??[]),row.topology.left,row.topology.right]) {\n            if(uri!==undefined)validateIdentifier(uri);\n          }\n        }\n      }\n      return records;\n    },\n  };\n}\nexport async function sweepStore({client,watchdog,table='pgsl_kv',measureFreeBytes,\n  maxDeleteBytes=8*GiB,batchBytes=64*1024*1024,maxSeconds=300,minFreeBytes=2*GiB,\n  dryRun=false,onPhase=async()=>{}}) {\n  const n=names(table);\n  if(typeof dryRun!=='boolean')throw Error('refusing sweep: invalid measurement mode');\n  if(typeof measureFreeBytes!=='function'||!watchdog)throw Error('refusing sweep: independent watchdog and headroom provider required');\n  for(const value of [maxDeleteBytes,batchBytes,maxSeconds,minFreeBytes])if(!Number.isSafeInteger(value)||value<=0)throw Error('refusing sweep: invalid bounded capacity');\n  if(batchBytes>128*1024*1024||maxDeleteBytes>16*GiB||maxSeconds>600||minFreeBytes<GiB)throw Error('refusing sweep: capacity exceeds maintenance bounds');\n  await verifyJournal(client,n);\n  const state=await client.query(`SELECT installed_at,clock_timestamp()-installed_at>=interval '1 hour' AS ready FROM ${n.state} WHERE singleton`);\n  if(state.rows.length!==1)throw Error('refusing sweep: root journal installation state unavailable');\n  if(!state.rows[0].ready&&!dryRun)return{status:'warming',deletedKeys:0,deletedBytes:0};\n  const release=await acquireCollectorLock(client,table);\n  let aborted,transaction=false,stopped=false,timer,monitorTask=Promise.resolve();\n  let deletedKeys=0,deletedBytes=0,pid,oid,walStart,freeAtStart;\n  const startedAt=Date.now(),deadline=startedAt+maxSeconds*1000;\n  const check=()=>{if(aborted)throw aborted;if(Date.now()>deadline)throw Error('sweep aborted: maintenance deadline');};\n  const cancel=async(reason)=>{\n    if(aborted||stopped)return;\n    aborted=Error('sweep aborted: '+reason);\n    if(pid)await watchdog.query('SELECT pg_cancel_backend($1)',[pid]).catch(()=>{});\n    // Also releases the fence when the collector is awaiting a network sample\n    // or its JS loop, rather than an active PostgreSQL statement.\n    await client.query('ROLLBACK').catch(()=>{});\n  };\n  const monitor=async()=>{\n    if(stopped||aborted)return;\n    try {\n      const q=await watchdog.query(`SELECT EXISTS(SELECT 1 FROM pg_locks\n        WHERE relation=$1 AND NOT granted AND pid<>$2) AS waiting,\n        pg_wal_lsn_diff(pg_current_wal_lsn(),$3::pg_lsn)::text AS wal_bytes`,[oid,pid,walStart]);\n      if(q.rows[0].waiting)return cancel('another table writer or maintenance operation queued');\n      const wal=Number(q.rows[0].wal_bytes);\n      if(!Number.isSafeInteger(wal)||wal<0||freeAtStart-wal<minFreeBytes+2*batchBytes)return cancel('headroom reserve exhausted');\n      check();\n    }catch{await cancel('watchdog, deadline or WAL measurement failed');}\n  };\n  try {\n    // Cover writes occurring while the external volume sample is acquired too.\n    walStart=(await watchdog.query('SELECT pg_current_wal_lsn()::text AS wal')).rows[0].wal;\n    freeAtStart=await measureFreeBytes();\n    if(!Number.isSafeInteger(freeAtStart)||freeAtStart<minFreeBytes+2*batchBytes)throw Error('sweep aborted: insufficient fresh headroom');\n    await client.query('BEGIN');\n    transaction=true;\n    await client.query(`SET LOCAL statement_timeout='30s'`);\n    await client.query(`SET LOCAL idle_in_transaction_session_timeout='10s'`);\n    // Dedup reads and later root writes share one adapter transaction. Fence\n    // readers too, so no writer can observe an orphan that this TX deletes.\n    await client.query(`LOCK TABLE ${n.relation} IN ACCESS EXCLUSIVE MODE NOWAIT`);\n    const identity=await client.query(`SELECT pg_backend_pid() AS pid,to_regclass($1)::oid AS oid,\n      pg_current_wal_lsn()::text AS wal,clock_timestamp()-interval '1 hour' AS cutoff`,[n.relation]);\n    ({pid,oid}=identity.rows[0]);\n    timer=setInterval(()=>{monitorTask=monitorTask.then(monitor);},100);\n    timer.unref();\n    await verifyJournal(client,n);\n    const unknown=await client.query(`SELECT 1 FROM ${n.relation}\n      WHERE CASE WHEN octet_length(k)<6 THEN true\n        WHEN substring(k FROM 1 FOR 5)<>decode('7067736c00','hex') THEN true\n        ELSE get_byte(k,5) NOT IN(78,73,66,76,82,86,79,87,80,65,88,67) END LIMIT 1`);\n    if(unknown.rows.length)throw Error('refusing sweep: unknown key namespace');\n    const malformedNodes=await client.query(`SELECT 1 FROM ${n.relation}\n      WHERE substring(k FROM 1 FOR 6)=decode('7067736c004e','hex')\n        AND (octet_length(k)<>27 OR CASE WHEN octet_length(k)>6 THEN get_byte(k,6) ELSE -1 END NOT IN(1,2))\n      LIMIT 1`);\n    if(malformedNodes.rows.length)throw Error('refusing sweep: malformed node key');\n    const live=await collectLive(retainedReader(client,n,identity.rows[0].cutoff,check),{traversalBatchSize:4096});\n    check();\n    if(!live.keys.size||live.stats.danglingRoots.length||live.stats.unreadableNodes)throw Error('refusing sweep: incomplete retained root closure');\n    await client.query('CREATE TEMP TABLE pgsl_sweep_live(k bytea PRIMARY KEY) ON COMMIT DROP');\n    const keys=[...live.keys];\n    for(let i=0;i<keys.length;i+=4000){check();await client.query('INSERT INTO pgsl_sweep_live SELECT unnest($1::bytea[]) ON CONFLICT DO NOTHING',[keys.slice(i,i+4000).map(k=>Buffer.from(k,'hex'))]);}\n    await onPhase('marked');check();\n    if(dryRun){\n      await monitor();check();\n      stopped=true;clearInterval(timer);await monitorTask;check();\n      await client.query('ROLLBACK');transaction=false;\n      return{status:'measured',liveKeys:live.keys.size,liveNodes:live.stats.liveNodes,\n        liveNodeBytes:live.stats.liveNodeBytes,markMilliseconds:Date.now()-startedAt,deletedKeys:0,deletedBytes:0};\n    }\n    // Only key+length metadata is materialized, never a second payload table.\n    await client.query(`CREATE TEMP TABLE pgsl_sweep_candidates ON COMMIT DROP AS\n      SELECT source.k,octet_length(source.v)::bigint AS bytes\n      FROM ${n.relation} source WHERE\n        (get_byte(source.k,5) IN(78,73,66,76,82,86,87) OR\n          (get_byte(source.k,5)=80 AND substring(source.k FROM octet_length(source.k)-3 FOR 4)=decode('00000002','hex')))\n        AND NOT EXISTS(SELECT 1 FROM pgsl_sweep_live live WHERE live.k=source.k)`);\n    await client.query('CREATE UNIQUE INDEX ON pgsl_sweep_candidates(k)');\n    for(;;){\n      check();await monitor();check();\n      const fresh=await measureFreeBytes();\n      if(!Number.isSafeInteger(fresh)||fresh<minFreeBytes+2*batchBytes)throw Error('sweep aborted: fresh headroom reserve exhausted');\n      const rows=await client.query('SELECT k,bytes FROM pgsl_sweep_candidates ORDER BY k LIMIT 256');\n      if(!rows.rows.length||deletedBytes>=maxDeleteBytes)break;\n      const batch=[];let bytes=0;\n      for(const row of rows.rows){\n        const size=Number(row.bytes);\n        if(!Number.isSafeInteger(size)||size<0||size>batchBytes)throw Error('refusing sweep: orphan value exceeds deletion batch bound');\n        if(batch.length&&(bytes+size>batchBytes||deletedBytes+bytes+size>maxDeleteBytes))break;\n        if(!batch.length&&deletedBytes+size>maxDeleteBytes)break;\n        batch.push(row.k);bytes+=size;if(bytes>=batchBytes)break;\n      }\n      if(!batch.length)break;\n      const result=await client.query(`DELETE FROM ${n.relation} source WHERE source.k=ANY($1::bytea[])\n        AND NOT EXISTS(SELECT 1 FROM pgsl_sweep_live live WHERE live.k=source.k)`,[batch]);\n      deletedKeys+=result.rowCount??0;deletedBytes+=bytes;\n      await client.query('DELETE FROM pgsl_sweep_candidates WHERE k=ANY($1::bytea[])',[batch]);\n      await onPhase('deleted');check();\n    }\n    await client.query(`DELETE FROM ${n.roots} WHERE retired_at<$1`,[identity.rows[0].cutoff]);\n    await monitor();check();\n    stopped=true;clearInterval(timer);await monitorTask;check();\n    await client.query('COMMIT');\n    transaction=false;\n  }catch(error){\n    stopped=true;if(timer)clearInterval(timer);\n    await monitorTask.catch(()=>{});\n    if(transaction)await client.query('ROLLBACK').catch(()=>{});\n    if(aborted)throw aborted;\n    throw error;\n  }finally{\n    stopped=true;if(timer)clearInterval(timer);\n    await release();\n  }\n  // PostgreSQL ordinary VACUUM returns dead heap/TOAST pages to the internal free\n  // space map. TRUNCATE false avoids a tail AccessExclusive lock on live traffic.\n  let vacuumed=false;\n  try {\n    await client.query(`SET statement_timeout='60s'`);\n    await client.query(`VACUUM (ANALYZE,TRUNCATE FALSE) ${n.relation}`);\n    vacuumed=true;\n  } catch {\n    // DELETE is already committed. Report this honestly so the next private run\n    // can retry ordinary VACUUM without implying that committed work rolled back.\n  }\n  return{status:'swept',deletedKeys,deletedBytes,vacuumed};\n}\n\nexport async function runPrivateSweep(){\n  const action=process.env.PGSL_SWEEP_ACTION??(process.argv.includes('--install')?'install':'off');\n  if(action==='off'){console.log('Private PGSL sweep is disabled.');return;}\n  if(!['install','measure','run'].includes(action))throw Error('unsupported private sweep action');\n  const connectionString=process.env.PGSL_PG_CONNSTR,token=process.env.RAILWAY_PROJECT_TOKEN;\n  const table=process.env.PGSL_SWEEP_TABLE??'pgsl_kv';\n  if(!connectionString)throw Error('PGSL_PG_CONNSTR is required');\n  const endpoint=new URL(connectionString);\n  if(!endpoint.hostname.endsWith('.railway.internal'))throw Error('private Railway database hostname is required');\n  const client=new Client({connectionString,application_name:'pgsl-private-sweep'});\n  const watchdog=new Client({connectionString,application_name:'pgsl-private-sweep-watchdog',statement_timeout:3000});\n  await client.connect();await watchdog.connect();\n  try{\n    if(action==='install'){await installSweep(client,{table});console.log('Root journal installed; deletion disabled for its first hour.');return;}\n    if(!token)throw Error('project-scoped Railway token is required for fresh volume headroom');\n    const serviceId=process.env.PGSL_SWEEP_POSTGRES_SERVICE_ID;\n    if(!serviceId)throw Error('exact postgres service ID is required');\n    const gql=async(query,variables={})=>{\n      const r=await fetch('https://backboard.railway.com/graphql/v2',{method:'POST',headers:{\n        'Content-Type':'application/json','Project-Access-Token':token},\n        body:JSON.stringify({query,variables}),signal:AbortSignal.timeout(5000)});\n      const body=await r.json();if(!r.ok||body.errors?.length)throw Error('private collector headroom query failed');return body.data;\n    };\n    const identity=await gql('{projectToken{projectId environmentId}}');\n    let sample;\n    const measureFreeBytes=async()=>{\n      if(!sample||Date.now()-sample.sampledAt>15000){\n        const data=await gql('query($p:String!,$e:String!){project(id:$p){volumes{edges{node{id volumeInstances{edges{node{serviceId mountPath sizeMB currentSizeMB}}}}}}} environment(id:$e){config(decryptVariables:false)}}',\n          {p:identity.projectToken.projectId,e:identity.projectToken.environmentId});\n        sample=collectorVolumeHeadroom(data,serviceId);\n      }\n      return sample.capacityBytes-sample.usedBytes;\n    };\n    console.log(JSON.stringify(await sweepStore({client,watchdog,table,measureFreeBytes,dryRun:action==='measure'})));\n  }finally{await watchdog.end();await client.end();}\n}\nif(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){\n  runPrivateSweep().catch(()=>{console.error('Private PGSL sweep failed; no database payload or credentials are logged.');process.exitCode=1;});\n}\n"};
if((process.env.PGSL_SWEEP_ACTION??'off')==='off'){
  console.log('Private PGSL sweep is disabled.');
}else{
  try{
    const directory=await mkdtemp(tmpdir()+'/pgsl-private-sweep-');
    await Promise.all(Object.entries(modules).map(([name,source])=>writeFile(directory+'/'+name,source,'utf8')));
    const {runPrivateSweep}=await import(directory+'/sweep.mjs');
    await runPrivateSweep();
  }catch{
    console.error('Private PGSL sweep failed; no database payload or credentials are logged.');
    process.exitCode=1;
  }
}
